def main():
    n = int(input())
    q_s = list(map(int, input().split()))
    a_s = list(map(int, input().split()))
    b_s = list(map(int, input().split()))

    max_servings = 0

    for number_of_a in range(min((q_s[i] // a_s[i] if a_s[i] > 0 else float('inf')) for i in range(n)) + 1):
        number_of_b = float('inf')
        for i in range(n):
            if b_s[i] > 0:
                number_of_b = min(number_of_b, (q_s[i] - a_s[i] * number_of_a) // b_s[i])
            elif a_s[i] * number_of_a > q_s[i]:
                number_of_b = -1
                break
        if number_of_b >= 0:
            max_servings = max(max_servings, number_of_a + number_of_b)

    print(max_servings)
